function RecordTable({rows}:{rows:RecordRow[]}) {return <div className="v3-table-wrap"><table className="v3-table"><thead><tr><th>Application</th><th>Institution</th><th>Workflow stage</th><th>Status</th><th>Due date</th><th>Priority</th></tr></thead><tbody>{rows.map(r=><tr key={r.ref}><td><NavLink className="v3-ref" to={'/applications/'+r.ref}><strong>{r.ref}</strong></NavLink><small className="v3-table-sub">{r.owner}</small></td><td>{r.institution}</td><td>{r.stage}</td><td><Badge tone={r.status==='Overdue'||r.status==='Needs clarification'?'rose':r.status==='Recommended'?'green':r.status==='Evidence pending'?'amber':'blue'}>{r.status}</Badge></td><td>{r.due}</td><td><Badge tone={r.priority==='High'?'rose':r.priority==='Medium'?'amber':'slate'}>{r.priority}</Badge></td></tr>)}</tbody></table></div>}
